insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1358.png', '1358-06-27', '1808-01-31', 'République de Raguse (Dubrovnik)', 'Republic of Ragusa (Dubrovnik)', 'La république maritime de Raguse, indépendante jusqu''à sa suppression par Napoléon en 1808, arborait un drapeau blanc à l''effigie de saint Blaise, son patron.', 'The maritime Republic of Ragusa, independent until Napoleon abolished it in 1808, flew a white flag bearing St Blaise, its patron saint.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1868.svg', '1868-01-01', '1918-10-29', 'Royaume de Croatie-Slavonie', 'Kingdom of Croatia-Slavonia', 'Le tricolore rouge-blanc-bleu, né pendant la révolution de 1848, devient en 1868 le drapeau du royaume autonome de Croatie-Slavonie, au sein de la couronne hongroise.', 'The red-white-blue tricolour, born in the 1848 revolution, became in 1868 the flag of the autonomous Kingdom of Croatia-Slavonia within the Hungarian crown.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1939.svg', '1939-08-26', '1941-04-10', 'Banovine de Croatie', 'Banovina of Croatia', 'Province autonome créée au sein du royaume de Yougoslavie par l''accord Cvetković-Maček de 1939.', 'An autonomous province created within the Kingdom of Yugoslavia by the 1939 Cvetković–Maček agreement.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1941.svg', '1941-04-10', '1945-05-08', 'État indépendant de Croatie', 'Independent State of Croatia', 'État satellite de l''Axe dirigé par le régime oustachi d''Ante Pavelić : le tricolore porte le damier et l''emblème « U » du mouvement.', 'An Axis puppet state run by Ante Pavelić''s Ustaše regime: the tricolour carried the chequerboard and the movement''s "U" emblem.');
